import traceback
from itertools import islice, cycle

from typing import List, Optional

from taf.rfrl.utilities.robot.RobotWrapper import RobotWrapper

from taf.rfrl.csv4all.resources.node.exceptions import WrongSwVersion
from taf.rfrl.csv4all.resources.node.node import Node
from taf.rfrl.csv4all.resources.test_cases import UpgradeTest, ParallelUpgradeTest
from taf.rfrl.csv4all.resources.test_cases.exceptions import IterationFailedError, TestPreconditionFailed, \
    RecoveryAttemptFailedError
from taf.rfrl.csv4all.resources.test_cases.csv4all_test import test_logger
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator, wrapper_decorator, function_wrapper


class ParallelSwDownloadTest(ParallelUpgradeTest):

    def __init__(self, nodes_details: List[dict], test_nodes_details: List[dict], iterations_per_node: int,
                 report: bool,
                 use_dcap: Optional[bool] = False, qc_domain: Optional[str] = None, qc_id: Optional[str] = None,
                 qc_project: Optional[str] = None, customers_list: Optional[list] = None,
                 report_comment: Optional[str] = None, sw_build: Optional[str] = None, topology: Optional[str] = None,
                 use_external_storage: Optional[bool] = False, download_path: Optional[str] = None,
                 stop_test_after_fail: bool = False,
                 artifactory_location: Optional[str] = "espoo2", package_suffix: Optional[str] = "A54",
                 l3_call_method: Optional[callable] = None, synchronize_software_on_passive: Optional[bool] = False,
                 virtualenv_dir: str = None, detailed_console_log: bool = True, collect_passed_logs: int = 0):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report, False, None,
                         use_dcap, qc_domain, qc_id, qc_project, customers_list, report_comment, sw_build, topology,
                         use_external_storage, download_path, True, stop_test_after_fail,
                         artifactory_location, package_suffix, l3_call_method, synchronize_software_on_passive,
                         virtualenv_dir, None, detailed_console_log, collect_passed_logs=collect_passed_logs)
        self.synchronize_software_on_passive = synchronize_software_on_passive
        self.use_testpackage = True
        self.hwf_migration_check = False
        self.reset_incrementation = False
        self.failed_nodes = set()

    def test_setup(self):
        super(UpgradeTest, self).test_setup()
        self.check_source_and_target_sw()
        self.download_builds_from_wft({node.target_sw for node in self.test_nodes if node.target_sw},
                                      download_candidate=False)
        self.prepare_uboot_scripts()
        self.set_sw_path_for_nodes()
        for node in self.test_nodes:
            self._set_current_logs_dir(node)
            self.remove_hwf_flag(node)
            if self.uboot.uboot_scripts_prepared:
                self.perform_uboot_downgrade_if_needed(node)

    def test(self):
        try:
            self.run_iteration_precondition()
            self.failed_nodes = self.test_operation(None)
        except Exception as e:
            self.stop_test_log_tracing(self.current_logs_dir)
            self.gather_mumin_logs_and_snapshot()
            test_logger("Iteration Failed!", "error")
            test_logger(e, "error")
            test_logger(traceback.format_exc(), log_level="debug", console=False)

            raise

        if self.failed_nodes:
            raise IterationFailedError(f"Iteration Failed. Issues detected on nodes : {self.failed_nodes}")
        if self.l3_call_method and not self.l3_call_result:
            raise IterationFailedError("Iteration Failed. L3 Call failed.")

    @wrapper_decorator
    def _precondition(self, node):
        self._set_current_logs_dir(node)
        self.check_active_sw(node, node.source_sw)

    def test_operation(self, node):
        self.set_timestamp_reporting_and_kpi()
        self.sw_download_test()
        return self.failed_nodes

    def sw_download_test(self):
        with RobotWrapper("Software Download Test", "kw"):
            self._set_current_logs_dir(None)
            if self.check_nodes_state_before_operation(operation="download"):
                self.failed_nodes.update(self.download_sw_operation())
            else:
                self.gather_mumin_logs_and_snapshot('update')
            if self.l3_call_method:
                self.l3_call_result = self.execute_l3_call_scenario()

    @method_decorator()
    def download_sw_operation(self):
        operation = "download"
        for node in self.test_nodes:
            node.target_sw_path = next(node.iter_target_sw_list)
        try:
            self.multi_runner.start_log_tracing_all_nodes()
            self.multi_runner.start_watching_alarms_on_all_nodes()
            self.parallel_live_update_precheck()
            self.gather_blackbox_and_set_reset_counter(operation)
            self.perform_multi_node_sw_download()
            self.failed_nodes_during_download = self.run_test_verification(None, operation=operation)
            return self.failed_nodes_during_download
        except Exception as e:
            if "not completed within timeout" in str(e):
                for node in self.test_nodes:
                    self.restart_admin_connection(node)
                    node.wait_till_sw_download_finish()
            return self.exception_handling_parallel(operation, e)

    @method_decorator()
    def report_results_to_uuf_dashboard(self):
        pass

    @function_wrapper
    def perform_multi_node_sw_download(self):
        download_results = self.multi_runner.run_operations_as_threads_and_return(self.test_nodes, Node.download_sw)
        if download_results.get("Failed"):
            for node_alias in download_results["Failed"].keys():
                node = self.node_factory.get_node_by_alias(self.nodes, node_alias)
                if "not completed within timeout" in str(download_results["Failed"][node_alias]):
                    node.wait_till_sw_download_finish()
            raise Exception("Multi node SW Download failed")

    @function_wrapper
    def verify_multi_node_planned_sw(self):
        planned_sw_results = self.multi_runner.run_operations_as_threads_and_return(self.test_nodes,
                                                                                    Node.verify_planned_sw)
        if planned_sw_results.get("Failed"):
            test_logger(f"Planned SW verification failed for nodes: {list(planned_sw_results['Failed'].keys())}",
                        "ERROR")
        return {node for node in {*planned_sw_results["Failed"].keys()}}

    @method_decorator()
    def verify_planned_sw(self, node):
        try:
            node.verify_planned_sw()
            return set()
        except WrongSwVersion:
            test_logger(f"Planned SW verification failed for node: {node.node_alias}", "ERROR")
            return {node.node_alias}

    def run_test_verification(self, node, hw_timer: int = None, alarm_timer: int = None, operation: str = None):
        failed_nodes = self.multi_runner.verify_all_nodes(hw_timer, alarm_timer)
        failed_nodes.update(self.multi_runner.verify_mplane())
        failed_nodes.update(self.verify_multi_node_planned_sw())
        failed_nodes.update(self.multi_runner.stop_logs_and_verify_on_all_nodes(f"{self.current_logs_dir}/{operation}",
                                                                                node, self.reset_incrementation))

        if failed_nodes or not self.passed_logs_gathered:
            self.gather_mumin_logs_and_snapshot()
        return failed_nodes

    @method_decorator()
    def set_sw_path_for_nodes(self):
        for node in self.test_nodes:
            target_sw_paths = {sw_path for sw_build, sw_path in self.wft.target_sw_dict.items()
                               if sw_build.startswith(node.target_sw)}
            target_sw_paths_list = list(islice(cycle(target_sw_paths), self.iterations_per_node + 1))
            node.iter_target_sw_list = iter(target_sw_paths_list)
            new_line = '\n'
            test_logger(f"{node.node_alias} will use:\n{new_line.join([path for path in target_sw_paths])}")

    @method_decorator()
    def check_nodes_state_before_operation(self, operation: str = "update"):
        failed_nodes = self.precheck_method()
        if failed_nodes:
            self.failed_nodes_during_download.update(failed_nodes)
            self.gather_mumin_logs_and_snapshot(f"before_{operation}")
            try:
                self.run_recovery_method(failed_nodes)
            except RecoveryAttemptFailedError:
                self.failed_nodes.update(failed_nodes)
            return False
        return True
